def parse_override_key(key: str) -> ParsedOverrideKey:
    """按 r3 白名单解析 override 键；非法形状 raise PayOrderKeyError（=ValueError）。

    词法：``<family><subject>[@<region_id>][#<source>]``。@ 必须先于 #；
    空词位（悬空 @ / #）、未知 family/subject、priority 族带 #、非军饷带 # 一律非法。
    本函数纯词法，不查 regions 表（region 存在性由物化端校验，防 @SX 类幻影 region）。
    """
    raw = str(key or "")
    body = raw
    source = ""
    if "#" in body:
        body, _, source = body.partition("#")
        if source not in _HAIRCUT_SOURCES:
            raise PayOrderKeyError(f"override 键 {raw!r}：#饷源后缀仅限 province/central")
    region = ""
    if "@" in body:
        body, _, region = body.partition("@")
        if not region:
            raise PayOrderKeyError(f"override 键 {raw!r}：@后 region_id 为空")
    if "@" in region or "#" in region:
        raise PayOrderKeyError(f"override 键 {raw!r}：scope 后缀顺序须为 @region#source")
    for family in (HAIRCUT_FAMILY, *_PRIORITY_FAMILIES):
        if body.startswith(family):
            subject = body[len(family):]
            break
    else:
        raise PayOrderKeyError(f"override 键 {raw!r}：未知键族（须 due_priority_*/arrears_priority_*/due_haircut_bp_*）")
    if family == HAIRCUT_FAMILY:
        if subject not in DUE_SUBJECTS:
            raise PayOrderKeyError(f"override 键 {raw!r}：未知折发科目 {subject!r}")
        if source and subject != "军饷":
            raise PayOrderKeyError(f"override 键 {raw!r}：饷源后缀仅军饷科目合法")
    else:
        legal = DUE_SUBJECTS if family == DUE_PRIORITY_FAMILY else ARREARS_SUBJECTS
        if subject not in legal:
            raise PayOrderKeyError(f"override 键 {raw!r}：{family}*/ 未知科目 {subject!r}")
        if source:
            # r3：序无饷源维度，# 后缀非法
            raise PayOrderKeyError(f"override 键 {raw!r}：priority 键族不允许 #饷源后缀")
    return ParsedOverrideKey(family=family, subject=subject, region=region, source=source)

def _humanize_condition(text: str) -> str:
    """Formal character-condition DSL → display labels; free prose passes through unchanged."""
    if not text:
        return text
    character_condition = re.fullmatch(
        r"\s*character\.([^.]+)\.([A-Za-z_]+)\s*(==|!=|>=|<=|>|<)\s*(.+?)\s*",
        text,
    )
    if not character_condition:
        # N6: no vocabulary replace on free prose / non-formal condition text in transport.
        return text
    name, field, op, value = character_condition.groups()
    if field == "loyalty" and re.fullmatch(r"\d+", value):
        if op in {">=", ">"}:
            return f"{name}忠诚回稳"
        if op in {"<=", "<"}:
            return f"{name}忠诚未稳"
        return f"{name}忠诚非通常取值"
    label = _CHARACTER_CONDITION_FIELD_LABELS.get(field, field)
    op_label = _CONDITION_OPERATOR_LABELS.get(op, op)
    value_label = _humanize_condition_value(field, value)
    return f"{name}{label}{op_label}{value_label}"

def parse_agent_json(raw: str, stage: str) -> Dict[str, Any]:
    text = strip_json_fence(raw)
    # 试 1：原文直解
    try:
        data = json.loads(text)
    except json.JSONDecodeError:
        data = None
    # 试 2：截 {...} 最外层再解
    if data is None:
        start = text.find("{")
        end = text.rfind("}")
        if start < 0 or end <= start:
            abort_llm_contract(stage, "没有返回 JSON object", raw)
        snippet = text[start : end + 1]
        try:
            data = json.loads(snippet)
        except json.JSONDecodeError:
            data = None
        # 试 3：净化 control char（\r\v\f\x00-\x1f 等）后再解
        if data is None:
            cleaned = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f]", "", snippet)
            try:
                data = json.loads(cleaned)
            except json.JSONDecodeError:
                data = None
        # 试 4：截取首个合法平衡的 {...} 子串（防 LLM 重发拼接）
        if data is None:
            depth = 0
            in_str = False
            esc = False
            best_end = -1
            for i, ch in enumerate(snippet):
                if esc:
                    esc = False
                    continue
                if ch == "\\" and in_str:
                    esc = True
                    continue
                if ch == '"':
                    in_str = not in_str
                    continue
                if in_str:
                    continue
                if ch == "{":
                    depth += 1
                elif ch == "}":
                    depth -= 1
                    if depth == 0:
                        best_end = i
                        break
            if best_end > 0:
                first_block = snippet[: best_end + 1]
                first_block = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f]", "", first_block)
                try:
                    data = json.loads(first_block)
                except json.JSONDecodeError as error:
                    raise LLMContractError(
                        f"{stage} 输出不是合法 JSON：{error}\n原始输出：{raw[:800]}",
                        raw_value=raw,
                    ) from error
            else:
                raise LLMContractError(
                    f"{stage} 输出不是合法 JSON\n原始输出：{raw[:800]}",
                    raw_value=raw,
                )
    if not isinstance(data, dict):
        abort_llm_contract(stage, "顶层必须是 JSON object", raw)
    return data

def _investigation_declaration(
    sel: Mapping[str, object] | None,
) -> Dict[str, object]:
    """#1896 4a 对查案密令的声明读口：查法/投入强度/所查事实/传话/知情反应。

    形状（ADR 0120 后出查案修订）——按人物当月真实办事声明，不读自由文本：
    - effort:   0..1 的**投入强度**（敷衍/停办 → 0）。只是"下了多大劲"，
                引擎另按承办人真实处境（能力/是否到差/未结差务带宽）折算本月实投。
                缺声明或不是数字 = **无效声明**（invalid），不是合法的零投入——
                明确停办只有一种写法：effort: 0。
    - fact_key: str，本月下手的罪证；人物没下手处就不给，代码不代选。
    - method:   查法（人物本月怎么查，原样落账）
    - tip_off:  {source} 真实通风报信：确有人经关系网把话递到被查者
    - spoliation: {effect, fact_key} 被查者知情后的毁证选择
    - suppression: {form} 被查者知情后的压案（行贿说项之类）声明

    奏报（memorial_text）不在此读口内：谎奏不造罪、不抹证（P6 实况/奏报分轨）。
    """
    item = sel if isinstance(sel, Mapping) else {}
    out: Dict[str, object] = {}
    raw_effort = item.get("effort", item.get("投入"))
    if raw_effort is None:
        out["invalid"] = "查案密令缺少 effort 声明（敷衍/停办请显式给 0）"
    else:
        intensity = _declared_intensity(raw_effort)
        if intensity is None:
            out["invalid"] = "查案密令的 effort 不是 0..1 的有限数字"
        else:
            out["intensity"] = intensity
    fact = str(item.get("fact_key", item.get("所查事实")) or "").strip()
    if fact:
        out["fact_key"] = fact
    raw_method = item["method"] if "method" in item else item.get("查法")
    if raw_method is not None and not isinstance(raw_method, (Mapping, list)):
        method = str(raw_method)
        if method != "":
            out["method"] = method
    tip = item.get("tip_off", item.get("通风报信"))
    if isinstance(tip, Mapping):
        source = str(tip.get("source", tip.get("递话人")) or "").strip()
        if source:
            out["tip_off"] = {"source": source}
    spoil = item.get("spoliation", item.get("毁证"))
    if isinstance(spoil, Mapping):
        effect = str(spoil.get("effect") or "harder").strip()
        if effect in ("harder", "gone"):
            out["spoliation"] = {
                "effect": effect,
                "fact_key": str(spoil.get("fact_key") or fact or "").strip(),
                "knowledge_source": str(
                    spoil.get("knowledge_source", spoil.get("知情来源")) or ""
                ),
            }
    suppress = item.get("suppression", item.get("压案"))
    if isinstance(suppress, Mapping):
        raw_form = suppress["form"] if "form" in suppress else suppress.get("方式")
        if raw_form is not None and not isinstance(raw_form, (Mapping, list)):
            form = str(raw_form)
            if form != "":
                out["suppression"] = {"form": form}
    return out

def _codex_final_text(obj: object) -> str:
    if not isinstance(obj, dict):
        return ""
    typ = str(obj.get("type") or obj.get("event") or "")
    if "delta" in typ:
        return ""
    # 防御性兼容 codex `--json` 的 item.* 形态（如 {"type":"item.completed",
    # "item":{"type":"agent_message","text":"…"}}）：最终 agent message 可能嵌在 item.text
    # 里。只取 agent_message 类 item，忽略 reasoning/tool/plan item，避免把真实邸报当成空
    # 输出误判失败（codex correctness）。与下面的顶层 message/text 形态并存，互不影响。
    item = obj.get("item")
    if isinstance(item, dict):
        item_type = str(item.get("type") or "")
        if item_type in ("", "agent_message") or "message" in item_type:
            value = item.get("text") or item.get("content") or item.get("message")
            if isinstance(value, str) and value:
                return value
    for key in ("message", "content", "text", "final", "last_message"):
        value = obj.get(key)
        if isinstance(value, str) and value:
            return value
        if isinstance(value, dict):
            nested = value.get("content") or value.get("text") or value.get("message")
            if isinstance(nested, str) and nested:
                return nested
    return ""

def _apply_dossier_participant_items(
    db: GameDB,
    state: GameState,
    extracted: Dict[str, object],
    *,
    items_key: str,
    authority_set: set,
    not_in_batch_msg: str,
) -> List[Dict[str, object]]:
    """Shared control flow for public/secret roster apply; fields stay separate.

    items_key / authority_set / not_in_batch_msg stay caller-owned — never union
    the two closed authority sets, never share a field-name or result slot.
    Missing authority is an empty closed set; never reconstruct from live DB.
    """
    results: List[Dict[str, object]] = []
    if not isinstance(authority_set, set):
        authority_set = set()
    for item in extracted.get(items_key) or []:
        if not isinstance(item, dict):
            results.append({
                "rejected": True, "category": "invalid_shape", "item": item,
            })
            continue
        try:
            dossier_id = _parse_sqlite_id(item.get("dossier_id"))
            if dossier_id not in authority_set:
                raise ValueError(not_in_batch_msg)
            character_id = str(item.get("character_id") or "").strip()
            delegator_id = str(item.get("delegator_id") or "").strip()
            tier = str(item.get("tier") or "").strip()
            if not character_id:
                raise ValueError("追加参与人物不能为空")
            if tier not in {"主办", "协办", "知情"}:
                raise ValueError("追加参与层级必须为主办/协办/知情")
            if not delegator_id:
                raise ValueError("追加参与人必须注明委派人")
            added = db.append_decree_dossier_participants(dossier_id, [{
                "character_id": character_id,
                "tier": tier,
                "role": str(item.get("role") or ""),
                "delegator_id": delegator_id,
            }], state=state, commit=False)
            if not added:
                # Exact durable duplicate is the only no-write success case.
                existing = db.get_decree_dossier(dossier_id) or {}
                if not any(
                    row.get("character_id") == character_id
                    and row.get("tier") == tier
                    and row.get("role") == str(item.get("role") or "")
                    and row.get("delegator_id") == delegator_id
                    for row in existing.get("participant_roster", [])
                ):
                    raise ValueError("参与人未实际加入案卷")
            persisted = added[0] if added else {
                "character_id": character_id, "tier": tier,
            }
            results.append({
                "dossier_id": dossier_id,
                "character_id": persisted["character_id"], "tier": persisted["tier"],
            })
        except (TypeError, ValueError, KeyError) as exc:
            results.append({
                "rejected": True, "category": "invalid_participant_roster",
                "reason": str(exc), "item": item,
            })
    return results

def _person_grounded_in_source(
    person_id: str,
    source_text: str,
    *,
    db: Any,
    content: Any,
    roster_forms: Optional[Dict[str, List[str]]] = None,
) -> bool:
    """窄确定性同人接地：原文出现该人规范名/别名，或可截断前缀且唯一落此人。

    禁散文关键词/第二套抽取语义；只做名册事实上的子串与前缀机械判定。
    """
    text = str(source_text or "")
    if not text:
        return False
    canon = _canon_person_id_key(person_id, db=db, content=content)
    if not canon:
        return False
    forms_index = roster_forms if roster_forms is not None else _all_roster_identity_forms(
        content=content,
    )
    my_forms = forms_index.get(canon) or _roster_identity_forms(canon, content=content)
    for form in my_forms:
        if form and form in text:
            return True
    # 可截断前缀：form 的真前缀（长≥2）出现在原文，且全名册仅此人的 form 命中该前缀
    for form in my_forms:
        if len(form) <= _MIN_PERSON_PREFIX_LEN:
            continue
        for n in range(_MIN_PERSON_PREFIX_LEN, len(form)):
            prefix = form[:n]
            if prefix not in text:
                continue
            owners: set[str] = set()
            for other_canon, other_forms in forms_index.items():
                for other in other_forms:
                    if other == prefix or other.startswith(prefix):
                        owners.add(other_canon)
                        break
            if owners == {canon}:
                return True
    return False

def create_armies_from_extraction(
    self,
    state: GameState,
    new_armies: List[Dict[str, object]],
    actor: str = "档房",
    commit: bool = True,
    origin_ref: str = "",
    require_origin: bool = False,
) -> List[Dict[str, object]]:
    """据 extractor 输出建新军队。同 id/name 已存在 → 把 manpower 当扩军增量。owner_power 必须是已知 power。"""
    valid_powers = {r["id"] for r in self.conn.execute("SELECT id FROM powers").fetchall()}
    created: List[Dict[str, object]] = []
    for raw in new_armies:
        if not isinstance(raw, dict):
            # 不再静默丢：留拒收记录（season 路本就被 validate_delta_shape 挡在
            # S6;issue 路历史即静默,容忍不升级——issue_strict=False,cmr S2 r1）。
            created.append({
                "rejected": True, "category": "invalid_enum",
                "reason": f"new_armies 含非 dict 项：{raw!r}",
                "item": raw, "issue_strict": False,
            })
            continue
        item = {POWER_FIELD_ALIASES.get(k, k) if False else k: v for k, v in raw.items()}
        # 规范键：复用 ARMY_FIELD_ALIASES（兼容中文）
        from ming_sim.constants import ARMY_FIELD_ALIASES as _AA
        item = {_AA.get(str(k).strip(), str(k).strip()): v for k, v in raw.items()}
        aid = str(item.get("id") or "").strip()
        if not aid:
            # ADR 0008 决定 1:缺 id = LLM 脏数据,逐项拒收留痕(invalid_enum),
            # 不再 raise 崩整月;同信封好军照建,坏一项不带走整批。
            created.append({
                "rejected": True, "category": "invalid_enum",
                "reason": "new_armies 缺 id（无法建军）",
                "item": raw,
            })
            continue
        owner = str(item.get("owner_power") or "ming").strip() or "ming"
        if owner not in valid_powers:
            # ADR 0008 决定 1:owner_power 幻觉 = 逐项拒收留痕(hallucinated_id)。
            created.append({
                "id": aid, "owner_power": owner,
                "rejected": True, "category": "hallucinated_id",
                "reason": f"new_armies owner_power '{owner}' 不在 powers 表（无法建军 {aid}）",
                "item": raw,
            })
            continue
        name = str(item.get("name") or aid).strip()
        # 查重：同 id 或 同 name → 转 manpower 扩军增量
        existing = self.conn.execute(
            "SELECT id, name FROM armies WHERE id = ? OR name = ?", (aid, name)
        ).fetchone()
        if existing is not None:
            manpower = item.get("manpower")
            if manpower is None:
                # ADR 0008 决定 1:命中已有军但无扩军增量 = 无意义项,逐项拒收留痕。
                created.append({
                    "id": aid, "rejected": True, "category": "invalid_enum",
                    "reason": f"new_armies 重复 id/name '{aid}' 且无 manpower（无扩军增量）",
                    "item": raw, "issue_strict": False,  # 历史 print-skip,结案路容忍
                })
                continue
            try:
                if isinstance(manpower, (bool, float)):
                    raise ValueError("非整数")
                delta = int(manpower)
            except (TypeError, ValueError):
                # ADR 0008 决定 1:扩军增量非整数 = LLM 脏数据,逐项拒收留痕。
                created.append({
                    "id": aid, "rejected": True, "category": "invalid_enum",
                    "reason": f"new_armies '{aid}' manpower 非整数：{manpower!r}",
                    "item": raw, "issue_strict": False,  # 历史 print-skip,结案路容忍
