def _normalize_event_terminal_reason(ev: Event, raw: object) -> str:
    label = re.sub(r"\s+", "", str(raw or ""))
    if not label:
        return ""
    allowed = getattr(ev, "terminal_reason_labels", []) or []
    for canonical in allowed:
        if label == re.sub(r"\s+", "", canonical):
            return canonical
    return ""

def _ground_relative_pay_order_deadlines(result: Dict[str, Any], db: Any) -> Dict[str, Any]:
    """在既有抽取适配缝把结构化相对月数落成 active-through 绝对 turn。"""
    row = db.conn.execute("SELECT turn FROM game_state WHERE id=1").fetchone()
    if row is None:
        return result
    current_turn = int(row["turn"])
    drafts = result.get("drafts")
    items = drafts if isinstance(drafts, list) else [result]
    for item in items:
        if not isinstance(item, dict) or item.get("dossier_action_type") != "pay_order_override":
            continue
        for entry in item.get("entries") or []:
            if not isinstance(entry, dict):
                continue
            if "duration_months" in entry:
                duration = entry.pop("duration_months")
                if isinstance(duration, bool) or not isinstance(duration, int) or duration <= 0:
                    raise ValueError(f"override 相对期限 duration_months 须为正整数：{duration!r}")
                entry["until_turn"] = current_turn + duration - 1
            elif "until_turn" in entry and (
                isinstance(entry["until_turn"], bool)
                or not isinstance(entry["until_turn"], int)
                or entry["until_turn"] < current_turn
            ):
                raise ValueError(f"override until_turn 已过期或无效：{entry['until_turn']!r}")
    return result

def project_applicable_authorities(
    self, turn: int, dossier: Mapping[str, object],
) -> List[Dict[str, object]]:
    """#611 unique applicability projection over durable authority rows.

    Actors = character executor ∪ roster 主办/协办 (never payload assignee).
    Domains = only the typed canonical key target_kind:target_id.
    """
    actors: set[str] = set()
    executor_id = str(dossier.get("executor_id") or "").strip()
    executor_kind = str(dossier.get("executor_kind") or "").strip()
    if executor_id and executor_kind in {"", "character"}:
        actors.add(executor_id)
    roster = dossier.get("participant_roster") or []
    if isinstance(roster, str):
        try:
            roster = json.loads(roster)
        except (TypeError, ValueError):
            roster = []
    if isinstance(roster, list):
        for entry in roster:
            if not isinstance(entry, dict):
                continue
            if str(entry.get("tier") or "").strip() not in {"主办", "协办"}:
                continue
            character_id = str(entry.get("character_id") or "").strip()
            if character_id:
                actors.add(character_id)
    target_kind = str(dossier.get("target_kind") or "").strip()
    target_id = str(dossier.get("target_id") or "").strip()
    domains: set[str] = set()
    if target_kind and target_id:
        domains.add(f"{target_kind}:{target_id}")
    if not actors or not domains:
        return []
    projected: List[Dict[str, object]] = []
    for holder_id in sorted(actors):
        for row in self.list_active_authorities(int(turn), holder_id=holder_id):
            if str(row.get("scope") or "") not in domains:
                continue
            projected.append({
                "id": int(row["id"]),
                "holder_id": str(row["holder_id"]),
                "privilege": str(row["privilege"]),
                "scope": str(row["scope"]),
                "effective_turn": int(row["effective_turn"]),
                **(
                    {"expires_turn": int(row["expires_turn"])}
                    if row.get("expires_turn") is not None else {}
                ),
            })
    projected.sort(key=lambda item: int(item["id"]))
    return projected

def is_stream_activity_event(event: Any) -> bool:
    """空转活动唯一权威（召对 web 流 / run_agent_text 同用；禁平行分叉）。

    活动：RunContent 有正文、reasoning 增量、工具生命周期、终包到达。
    终包计入活动：本 attempt 已完成产出，不得在 RunOutput/RunCompleted 边界空转误杀。
    活动 ≠ 已呈现正文；不据此禁止重试。
    """
    name = type(event).__name__
    if name in ("RunOutput", "RunCompletedEvent"):
        return True
    if getattr(event, "event", "") == "RunContent" and getattr(event, "content", None):
        return True
    rdelta = getattr(event, "reasoning_content", None)
    if isinstance(rdelta, str) and bool(rdelta):
        return True
    return name in (
        "ToolCallStartedEvent",
        "ToolCallCompletedEvent",
    )

def main() -> int:
    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s %(levelname)s %(name)s: %(message)s",
    )
    args = _args()
    content = GameContent.load()
    bind_content(content)
