def _field_raw(obj: Mapping[str, Any], spec: FieldSpec) -> Any:
    if spec.name in obj:
        return obj.get(spec.name)
    if spec.zh in obj:
        return obj.get(spec.zh)
    return None

def _agent_run_accepts_stream(agent: object) -> bool:
    """可确证的流式能力：显式属性或 run 签名声明 stream/stream_events/**kwargs。

    不能 inspect 时不猜「不支持」——返回 True，走流式；未知 TypeError 响亮上浮（0005）。
    不靠异常文本归因（票面研究项 / ADR 0142）。
    """
    explicit = getattr(agent, "supports_stream", None)
    if explicit is not None:
        return bool(explicit)
    run = getattr(agent, "run", None)
    if run is None:
        return False
    try:
        sig = inspect.signature(run)
    except (TypeError, ValueError):
        return True
    params = sig.parameters
    if any(p.kind == inspect.Parameter.VAR_KEYWORD for p in params.values()):
        return True
    return "stream" in params or "stream_events" in params

def list_unsettled_summons(db: Any) -> List[Dict[str, Any]]:
    """从故事账确定性投影未结传召；不解析自由叙事正文。"""
    rows = db.conn.execute(
        "SELECT id, night_id, person_names, tags FROM story_ledger_entries ORDER BY id"
    ).fetchall()
    projected: List[Dict[str, Any]] = []
    for row in rows:
        tags = json.loads(row["tags"] or "[]")
        if TAG_SUMMON_UNSETTLED not in tags or TAG_SUMMON_SETTLED in tags:
            continue
        origin = next(
            (str(tag)[len(_SUMMON_ORIGIN_PREFIX):] for tag in tags
             if str(tag).startswith(_SUMMON_ORIGIN_PREFIX)),
            "",
        )
        names = json.loads(row["person_names"] or "[]")
        if not origin or not names:
            continue
        person_name = str(names[0])
        projected.append({
            "entry_id": int(row["id"]), "night_id": int(row["night_id"]),
            "person_name": person_name, "origin_id": origin,
            "kind": _project_unsettled_summon_kind(db, tags, person_name),
            **({"travel_tone": _travel_tone_from_tags(tags)}
               if any(str(tag).startswith(_SUMMON_TRAVEL_TONE_PREFIX) for tag in tags)
               else {}),
        })
    return projected

def play_turn(session: GameSession) -> None:
    """一回合 CLI 驱动：召见 → 审阅 → 颁诏推演。"""
    snap = session.begin_turn()
    _print_header(session)
    if session.previous_summary:
        print(session.previous_summary)
        print()
    if snap.deaths_this_turn:
        names = "、".join(f"{d['name']}（{d['office']}）" for d in snap.deaths_this_turn)
        print(f"【讣闻】本{TURN_UNIT}卒：{names}\n")
    from ming_sim.issues import show_active_issues
    show_active_issues(session.db)

    pending_character: Optional[Character] = None
    while True:
        if session.current_phase() == TurnPhase.SUMMONING:
            character = pending_character or choose_minister(session)
            pending_character = None
            if character is None:
                action = review_directives(session)
            else:
                chat_action = minister_chat(session, character, selected=True)
                if chat_action == "dismiss":
                    continue
                if chat_action.startswith("summon:"):
                    pending_character = session.content.characters[chat_action.split(":", 1)[1]]
                    continue
                # court_break 或对话结束 → 审阅
                action = review_directives(session)
        else:
            action = review_directives(session)

        if action == "back":
            continue
        if action == "skip":
            turn_before = int(session.state.turn)
            failed_before = _failed_secret_order_ids(session, turn_before)
            try:
                # #1353 fold-in r8：颁诏/退朝前挂唯一 write_gate，使 resolve 收夜 drain 同流。
                _cli_write_gate(session)
                result = session.advance_without_decree()
                report = _submit_cli_decisions(session, result)
            except (ValueError, SettlementAbort, LLMUnavailable, LLMContractError) as error:
                # 跳过与颁诏共享可恢复结算语义：失败后留在本回合循环，允许重试。
                # #1353 fold-in r8：统一重试耗尽的 LLMUnavailable 不退出 CLI。
                # #1700：空 simulator 的 LLMContractError 同形，不落到 run_cli「程序中止」。
                print(f"\n{error}")
                _print_pending_action_failures(
                    _new_secret_order_failure_payloads(session, turn_before, failed_before)
                )
                continue
            _print_pending_action_failures(
                _new_secret_order_failure_payloads(session, turn_before, failed_before)
            )
            if result is not None:
                print(report)
                if getattr(session.state, "ended", False):
                    return
                if getattr(result, "advanced", False) or int(session.state.turn) > turn_before:
                    session.end_turn()
                    return
            else:
                return
            continue
        if action == "issue":
            turn_before = int(session.state.turn)
            failed_before = _failed_secret_order_ids(session, turn_before)
            try:
                # #1353 fold-in r8：颁诏/退朝前挂唯一 write_gate，使 resolve 收夜 drain 同流。
                _cli_write_gate(session)
                result = session.resolve_turn()
                report = _submit_cli_decisions(session, result)
            except (ValueError, SettlementAbort, LLMUnavailable, LLMContractError) as error:
                # 恢复态守门 / 结算中止 / 欠账耗尽（#1353 r8）/ 契约失败（#1700）：打印指引后留在
                # 本回合交互循环——玩家重按 issue/skip 即重试整段，CLI 不退出。
                print(f"\n{error}")
                _print_pending_action_failures(
                    _new_secret_order_failure_payloads(session, turn_before, failed_before)
                )
                continue

def _is_manual_special_decree_fallback(payload: Mapping[str, Any]) -> bool:
    """#1327/#1274 V-1 capture 空载/超时 fallback 同形；#1769 结算重写不得把它当成功拟旨。"""
    return (
