            changes.append({
                "power_id": power_id, "rejected": True,
                "category": "invalid_enum",
                "reason": "power_updates 不处理大明自身（ming），prompt 明文禁止",
                "item": {"power_id": power_id, "changes": raw_changes},
            })
            continue
