def _ming_settle_bases(db: Any) -> List[Tuple[str, Dict[str, Any], Dict[str, Any]]]:
    """① 明控且有 settle key 的省级基座；缺 key 出列，坏 JSON/现存坏结构响亮失败。"""
    out: List[Tuple[str, Dict[str, Any], Dict[str, Any]]] = []
    rows = db.conn.execute(
        "SELECT id, fiscal FROM regions WHERE controlled_by = 'ming' ORDER BY id"
    ).fetchall()
    for row in rows:
        region_id = str(row["id"])
        try:
            fiscal = json.loads(str(row["fiscal"] or "{}"))
        except (TypeError, ValueError) as exc:
            raise ValueError(
                f"fiscal_fact_brief：region {region_id} fiscal JSON 非法：{exc}"
            ) from exc
        if not isinstance(fiscal, dict):
            raise ValueError(f"fiscal_fact_brief：region {region_id} fiscal 非字典")
        if "settle" not in fiscal:
            continue
        settle = fiscal["settle"]
        if not isinstance(settle, dict):
            raise ValueError(f"fiscal_fact_brief：region {region_id} settle 非字典")
        st = settle.get("st")
        p = settle.get("p")
        if not isinstance(st, dict) or not isinstance(p, dict):
            raise ValueError(
                f"fiscal_fact_brief：region {region_id} settle.st/p 非字典"
            )
        out.append((region_id, st, p))
    return out

def _event_result_delta_event_ids(
    strategic_event_ids: set[str],
    extracted: Dict[str, object],
    person_changes: List[Dict[str, object]],
    ordered_deltas: Dict[str, list[tuple[str, object]]],
    ordered_effect_event_ids: dict[str, list[str]] | None,
) -> set[str]:
    """收集本批声明归属到战略事件的效果所触及的事件 id。"""
    result_ids: set[str] = set()

    def _collect_field(field: str) -> None:
        items = ordered_deltas.get(field) or []
        for index, _pair in enumerate(items):
            result_ids.update(_effect_event_ids(
                field, index, strategic_event_ids, ordered_effect_event_ids,
            ))

    if isinstance(extracted.get("region_delta"), dict):
        _collect_field("region_delta")
    if isinstance(extracted.get("army_delta"), dict):
        _collect_field("army_delta")
    if isinstance(extracted.get("power_updates"), dict):
        _collect_field("power_updates")
    for index, item in enumerate(person_changes):
        event_id = str(item.get("_effect_event_id") or "")
        if event_id and event_id in strategic_event_ids:
            result_ids.add(event_id)
    if isinstance(extracted.get("new_armies"), list):
        declared = (ordered_effect_event_ids or {}).get("new_armies", [])
        for index, _item in enumerate(extracted.get("new_armies") or []):
            event_id = declared[index] if index < len(declared) else ""
            if event_id and event_id in strategic_event_ids:
                result_ids.add(event_id)
    return result_ids

def _normalize_event_outcome_label(event_id: str, label: str, content: GameContent) -> str:
    allowed = _closed_outcome_labels(content, event_id)
    compact = re.sub(r"\s+", "", str(label or ""))
    if not compact:
        return ""
    for canonical in allowed:
        if compact == re.sub(r"\s+", "", canonical):
            return canonical
    alias = _STRATEGIC_EVENT_OUTCOME_LABEL_ALIASES.get(event_id, {}).get(compact, "")
    return alias if alias in allowed else ""

def restore_runtime() -> None:
    state.metrics.clear()
    state.metrics.update(metrics_snapshot)
    if content is not None:
        for name in list(content.characters):
            if name not in character_objects:
                del content.characters[name]
        for name, character in character_objects.items():
            content.characters[name] = character
            try:
                for attr in list(vars(character)):
                    if attr not in character_attrs.get(name, {}):
                        delattr(character, attr)
            except TypeError:
                pass
            for attr, value in character_attrs.get(name, {}).items():
                setattr(character, attr, value)

def is_deepseek_model(model: str) -> bool:
    """模型 id 属 DeepSeek 系（含 deepseek/ 前缀与 bare deepseek-* id）。"""
    raw = (model or "").strip().lower()
    if not raw:
        return False
    if raw.startswith("deepseek/"):
        return True
    return openai_model_id_without_provider(model).startswith("deepseek")

def _question_as_decision(question: Dict[str, object], *, event_id: str) -> Dict[str, object]:
    options = question.get("options") if isinstance(question.get("options"), list) else []
    cleaned = []
    for opt in options:
        if not isinstance(opt, dict):
            continue
        label = str(opt.get("label") or "")
        if not label.strip():
            continue
        cleaned.append({
            "label": label,
            "hint": str(opt.get("hint") or ""),
            **{
                key: opt[key] for key in opt
                if key not in {"label", "hint"} and opt[key] is not None
            },
        })
    return {
        "event_id": event_id,
        "title": str(question.get("title") or "") or "请旨",
        "context": str(question.get("context") or ""),
        "options": cleaned,
    }

