def resolve_disposition_credit_from_extraction(
    db: Any, state: Any, extracted: Dict[str, object],
) -> List[Dict[str, object]]:
    """处置映射：丢卒保车 / 包庇 / 查办(不记)。对象须为已暴露变形案卷。"""
    if not isinstance(extracted, dict):
        return []
    items = _person_change_items(extracted)
    if not items:
        return []

    by_dossier: Dict[int, List[Dict[str, object]]] = {}
    for it in items:
        did = _item_dossier_id(it)
        if did is None:
            continue
        by_dossier.setdefault(did, []).append(it)

    out: List[Dict[str, object]] = []
    for did, group in by_dossier.items():
        dossier = db.get_decree_dossier(int(did))
        if not isinstance(dossier, dict) or not _is_exposed_transformed(dossier):
            continue
        roster = _roster_entries(dossier)
        parties = project_execution_liability_parties(roster)
        primary_ids = {
            str(p["character_id"])
            for p in parties
            if str(p.get("responsibility") or "") == "primary"
            and str(p.get("character_id") or "").strip()
        }
        liability_ids = {
            str(p["character_id"])
            for p in parties
            if str(p.get("character_id") or "").strip()
        }

        punitive, covered, by_person_ctx, group_ctx = _group_person_sets(group)

        # 1) 丢卒保车：卒受惩、委派人未惩 → 两笔弃卒保车
        scapegoat_hit = False
        for pawn, car in _pawn_car_pairs(roster):
            if pawn in punitive and car not in punitive:
                scapegoat_hit = True
                ctx = by_person_ctx.get(pawn) or group_ctx
                out.extend(_write_scapegoat_pair(
                    db, state, did=did, pawn=pawn, car=car, context=ctx,
                ))
        if scapegoat_hit:
            continue

        # 2) 查办：惩处落在连坐责任面（主办/委派）→ 不记事件
        if punitive & liability_ids:
            out.append({
                "kind": None,
                "disposition": "查办",
                "dossier_id": did,
                "punitive": sorted(punitive & liability_ids),
                "edge_id": None,
            })
            continue

        # 3) 包庇：责任面求交（删 or covered 兜底逸出）
        cover_targets = (covered & liability_ids) or (covered & primary_ids)
        out.extend(_write_cover_backs(
            db, state,
            did=did,
            targets=cover_targets,
            punitive=punitive,
            by_person_ctx=by_person_ctx,
            group_ctx=group_ctx,
        ))
    return out

def _monthly_dossier_report_supply(
    self, turn: int, generated: object,
) -> Optional[Dict[int, Dict[str, object]]]:
    """校验本月密奏覆盖。无合资格案卷且产物为空时返回 None；不写库。"""
    candidates = {
        int(item["dossier_id"]): item
        for item in self.list_monthly_dossier_progress_nudges(int(turn))
    }
    if not candidates:
        if generated is None or generated == []:
            return None
        raise ValueError("无合资格长差案卷却收到本月密奏")
    if generated is None or generated == []:
        raise ValueError("合资格长差案卷缺少本月密奏")
    if not isinstance(generated, list):
        raise ValueError("合资格长差案卷缺少本月密奏")
    supplied: Dict[int, Dict[str, object]] = {}
    for item in generated:
        if not isinstance(item, dict):
            raise ValueError("长差月报格式无效")
        try:
            dossier_id = strict_int(item.get("dossier_id", 0))
            if dossier_id <= 0:
                raise ValueError("not positive")
        except (TypeError, ValueError) as exc:
            raise ValueError("长差月报案卷编号无效") from exc
        band = str(item.get("progress_band") or "").strip()
        text = str(item.get("memorial_text") or "")
        if dossier_id not in candidates or dossier_id in supplied or not band or not text.strip():
            raise ValueError("长差月报存在未知、重复或空白条目")
        supplied[dossier_id] = item
    if set(supplied) != set(candidates):
        raise ValueError("合资格长差案卷月报未完整覆盖")
    return supplied

def classify_directive_structured_kind(payload: Mapping[str, object]) -> str:
    """#658 旨意结构化互斥权威：'push' | 'ordinary' | 'empty'；并存响亮拒绝。

    extract / capture / staging / merge / ensure 共吃——禁第二份 triad↔target 判定。
    """
    has_push = imperial_push_target_dossier_id(payload) is not None
    has_triad = directive_payload_has_ordinary_triad(payload)
    if has_push and has_triad:
        raise ValueError(
            "旨意不得同时带普通结构化 triad 与御笔强推 target_dossier_id"
        )
    if has_push:
        return "push"
    if has_triad:
        return "ordinary"
    return "empty"

def _provenance_from_stored(value: object) -> Provenance:
    """从 ctx 持久值还原 Provenance（#146 恢复路）：兼容 Provenance 实例、已存的字符串值、
    历史误序列化的 'Provenance.<name>' 字面串、及非法/缺失值。非法/缺失回落 system_simulation。

    防静默丢源（Sourcery + gemini + coderabbit #175 concur）：Provenance 是 (str, Enum)，
    若曾把枚举实例 str() 落库会得到 'Provenance.player_decree'（而非值 'player_decree'），
    Provenance(...) 不匹配 → ValueError → 丢源退回 system_simulation。故分三层：
    ① 实例直接返回；② 纯值走 Provenance(value)；③ 'Provenance.<name>' 旧脏串剥前缀按成员名查回；
    仍无法识别才回落 system_simulation。"""
    if isinstance(value, Provenance):
        return value
    text = str(value or "system_simulation")
    try:
        return Provenance(text)
    except ValueError:
        pass
    # 历史误序列化：str(枚举实例) 落库的 'Provenance.player_decree' 脏串——剥前缀按成员名查回，
    # 不让旧档玩家来源静默退化成 system_simulation。
    if text.startswith("Provenance."):
        try:
            return Provenance[text.split(".", 1)[1]]
        except KeyError:
            pass
    return Provenance.system_simulation

def _parse_subject(subject_kind: object, subject_id: object) -> tuple[str, str]:
    kind = str(subject_kind or "").strip()
    if kind not in TEXTUAL_FACT_SUBJECT_KINDS:
        raise ValueError(
            f"textual fact subject_kind must be one of {sorted(TEXTUAL_FACT_SUBJECT_KINDS)}"
        )
    target = str(subject_id or "").strip()
    if not target:
        raise ValueError("textual fact subject_id cannot be empty")
    return kind, target

def _resolve_order_param(p: Dict[str, Any], key: str, default: tuple) -> tuple:
    """#653 override 序参（p[key]）验形：缺省=祖制默认序；在位必须是合法排列，
    否则 ValueError（fail-loud）。返回定长 tuple 供结算与 oracle 同源消费。"""
    raw = p.get(key)
    if raw is None:
        return default
    if isinstance(raw, str) or not isinstance(raw, (list, tuple)):
        raise ValueError(f"param {key} 非 list/tuple")
    if any(not isinstance(item, str) for item in raw):
        raise ValueError(f"param {key} 须为 {default} 的完整无重复排列：{raw!r}")
    if len(raw) != len(default) or set(raw) != set(default) or len(set(raw)) != len(raw):
        raise ValueError(f"param {key} 须为 {default} 的完整无重复排列：{raw!r}")
    return tuple(raw)

