def _entity_delta_has_work(
    raw: object,
    *,
    aliases: Dict[str, str],
    numeric_fields: tuple[str, ...],
    text_fields: tuple[str, ...] = (),
) -> bool:
    if not isinstance(raw, dict):
        return False
    numeric = set(numeric_fields)
    text = set(text_fields)
    for changes in raw.values():
        if not isinstance(changes, dict):
            continue
        for raw_field, value in changes.items():
            field = aliases.get(str(raw_field).strip(), str(raw_field).strip())
            if field in numeric and _nonzero_int(value):
                return True
            if field in text and _nonempty_text(value):
                return True
    return False

def _collect_disclosures_from_result(chain: Optional[Dict[str, Any]], result: Any) -> None:
    if chain is None or result is None:
        return
    pending = chain.setdefault("pending_disclosures", [])
    effects = getattr(result, "effects", None)
    applied = getattr(effects, "applied", []) if effects is not None else []
    for report in applied:
        if not isinstance(report, dict):
            continue
        for update in report.get("secret_order_updates") or []:
            if isinstance(update, dict) and update.get("disclosed"):
                item = {
                    "order_id": int(update["order_id"]),
                    "sim_note": str(update.get("sim_note") or ""),
                }
                if item not in pending:
                    pending.append(item)

def _clear_settlement_display_if_orphan(
    db: "GameDB", state: "GameState", *, reason: str,
) -> bool:
    """同谓词 clearer：快照在 ∧ 相位非常态前半段 → 清快照。settling/awaiting 不清。"""
    turn = int(state.turn)
    phase = str(state.turn_phase or "")
    if phase in FRONT_HALF_DONE_PHASES:
        return False
    if db.get_month_open_snapshot(turn) is None:
        return False
    db.clear_month_open_snapshot(turn)
    tlog(f"[month_open_snapshot] {reason} turn={turn} phase={phase}")
    return True

